/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import runQueue, { readLimit } from './dist/queue.js';
import { submit } from './dist/caller.js';
const job = (id, priority) => ({id, priority});
const pausedCalls = [];
const status = await submit([job('a', 1)], async j => { pausedCalls.push(j.id); });
assert.equal(readLimit('0'), 3);
assert.deepEqual(pausedCalls, ['a']);
console.log('PAUSE:', JSON.stringify({limit:readLimit('0'), pausedCalls, status}));
const started = [], completed = [], releases = [];
await runQueue([job('a', 1),job('b', 2)], '2', j => {
  started.push(j.id);
  return new Promise(resolve => releases.push(() => { completed.push(j.id); resolve(); }));
});
assert.deepEqual(started, ['a','b']);
assert.deepEqual(completed, []);
console.log('COMPLETION:', JSON.stringify({queueResolved:true,started,completed}));
releases.forEach(release => release());
const jobs = [job('b',2),job('a',1)];
await runQueue(jobs, '1', async () => {});
assert.deepEqual(jobs.map(j=>j.id), ['a','b']);
console.log('OWNERSHIP:', JSON.stringify({before:['b','a'],after:jobs.map(j=>j.id)}));
const failure = new Error('save failed');
const errors = [], failedStarts = [];
const listener = error => { errors.push(error); };
process.on('unhandledRejection', listener);
let queueRejected = false;
try {
  await runQueue([job('a',1),job('b',2)], '2', async j => {
    failedStarts.push(j.id);
    if (j.id === 'a') throw failure;
  });
} catch { queueRejected = true; }
await new Promise(resolve => setImmediate(resolve));
process.off('unhandledRejection', listener);
assert.equal(queueRejected,false);
assert.deepEqual(failedStarts,['a','b']);
assert.equal(errors[0],failure);
console.log('FAILURE:', JSON.stringify({queueRejected,started:failedStarts,unhandled:errors.map(e=>e.message)}));
NODE"

